const catalog={
  tops:{label:'Jacket cut',cuts:['Oversized','Cropped','Fitted'],colors:[['Cobalt','#244dff',0],['Cherry','#d52c43',285],['Acid','#c4eb36',65],['Ink','#25272d',205],['Cloud','#e8e5dd',160]],patterns:['Solid','Stripe','Check','Wave']},
  bottoms:{label:'Trouser cut',cuts:['Wide leg','Straight','Tapered'],colors:[['Graphite','#303238',0],['Denim','#416590',195],['Clay','#a45f4a',320],['Oat','#d9cfbb',140],['Black','#111216',0]],patterns:['Solid','Stripe','Check','Wave']},
  accessories:{label:'Accessory',cuts:['Shoulder bag','Crossbody','Mini tote'],colors:[['Silver','#bfc3cb',0],['Cobalt','#244dff',150],['Cherry','#d52c43',285],['Gold','#c69b45',55],['Black','#17181b',210]],patterns:['Solid','Stripe','Check','Wave']}
};
const state={section:'tops',tops:{cut:0,color:0,pattern:0},bottoms:{cut:0,color:0,pattern:0},accessories:{cut:0,color:0,pattern:0}};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const cutOptions=$('#cutOptions'),colorOptions=$('#colorOptions'),patternOptions=$('#patternOptions');
function renderControls(){const data=catalog[state.section],pick=state[state.section];$('#pieceLabel').textContent=data.label;$('#cutValue').textContent=data.cuts[pick.cut];$('#colorValue').textContent=data.colors[pick.color][0];$('#patternValue').textContent=data.patterns[pick.pattern];cutOptions.innerHTML=data.cuts.map((x,i)=>`<button class="choice ${i===pick.cut?'active':''}" data-index="${i}">${x}</button>`).join('');colorOptions.innerHTML=data.colors.map((x,i)=>`<button class="swatch ${i===pick.color?'active':''}" style="--swatch:${x[1]}" data-index="${i}" role="radio" aria-checked="${i===pick.color}" aria-label="${x[0]}"></button>`).join('');patternOptions.innerHTML=data.patterns.map((x,i)=>`<button class="pattern-choice ${i===pick.pattern?'active':''}" data-value="${x.toLowerCase()}" data-index="${i}" role="radio" aria-checked="${i===pick.pattern}" aria-label="${x}"></button>`).join('');updatePreview()}
function updatePreview(){for(const section of Object.keys(catalog)){const pick=state[section],hue=catalog[section].colors[pick.color][2],key=section==='accessories'?'acc':section==='tops'?'top':'bottom';document.documentElement.style.setProperty(`--${key}-hue`,`${hue}deg`);const pat=$(`.pattern-${key}`);pat.className=`pattern pattern-${key} ${catalog[section].patterns[pick.pattern].toLowerCase()}`}
 document.documentElement.style.setProperty('--top-scale',[1,.92,.86][state.tops.cut]);document.documentElement.style.setProperty('--bottom-scale',[1,.82,.68][state.bottoms.cut]);document.documentElement.style.setProperty('--acc-scale',[1,.9,.76][state.accessories.cut]);const d=catalog[state.section],p=state[state.section];$('#currentPiece').textContent=`${d.colors[p.color][0]} ${d.cuts[p.cut].toLowerCase()}`;$('#lookCode').textContent=`LOOK ${String(1+state.tops.cut*30+state.bottoms.cut*9+state.accessories.cut*3+state.tops.color).padStart(3,'0')}`}
function selectSection(section){state.section=section;$$('.step-tab').forEach(b=>{const active=b.dataset.section===section;b.classList.toggle('active',active);b.setAttribute('aria-selected',active)});const order=['tops','bottoms','accessories'];const next=order[(order.indexOf(section)+1)%3];$('#nextStep').innerHTML=section==='accessories'?'Finish outfit <span>→</span>':`Next: ${next[0].toUpperCase()+next.slice(1)} <span>→</span>`;renderControls()}
$$('.step-tab').forEach(b=>b.addEventListener('click',()=>selectSection(b.dataset.section)));
cutOptions.addEventListener('click',e=>{if(!e.target.dataset.index)return;state[state.section].cut=+e.target.dataset.index;renderControls()});colorOptions.addEventListener('click',e=>{if(!e.target.dataset.index)return;state[state.section].color=+e.target.dataset.index;renderControls()});patternOptions.addEventListener('click',e=>{if(!e.target.dataset.index)return;state[state.section].pattern=+e.target.dataset.index;renderControls()});
$('#nextStep').addEventListener('click',()=>{if(state.section==='tops')selectSection('bottoms');else if(state.section==='bottoms')selectSection('accessories');else showSummary()});
$('#surprise').addEventListener('click',()=>{for(const s of Object.keys(catalog)){state[s].cut=Math.floor(Math.random()*3);state[s].color=Math.floor(Math.random()*5);state[s].pattern=Math.floor(Math.random()*4)}renderControls()});
function showSummary(){const list=$('#summaryList');list.innerHTML=Object.keys(catalog).map(s=>{const p=state[s],d=catalog[s];return `<div class="summary-item"><span>${s}</span><strong>${d.colors[p.color][0]} · ${d.cuts[p.cut]} · ${d.patterns[p.pattern]}</strong></div>`}).join('');$('#summaryDialog').showModal()}
$('#openSummary').addEventListener('click',showSummary);$('#closeSummary').addEventListener('click',()=>$('#summaryDialog').close());$('#editAgain').addEventListener('click',()=>$('#summaryDialog').close());
$('#resetAll').addEventListener('click',()=>{for(const s of Object.keys(catalog))state[s]={cut:0,color:0,pattern:0};selectSection('tops');const t=$('#toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1600)});
let dragStart=null,rotation=0;$('#stage').addEventListener('pointerdown',e=>{dragStart=e.clientX;$('#stage').setPointerCapture(e.pointerId)});$('#stage').addEventListener('pointermove',e=>{if(dragStart===null)return;rotation=Math.max(-16,Math.min(16,(e.clientX-dragStart)/8));$('#outfit').style.transform=`rotateY(${rotation}deg)`});$('#stage').addEventListener('pointerup',()=>{dragStart=null;setTimeout(()=>$('#outfit').style.transform='',400)});
renderControls();
